/**
 * Agent Hub Router — Wildcard route for executing both design-time and dynamic agents.
 * Generated by Mindbricks Genesis Engine for the AgentHub service.
 */
const express = require("express");
const router = express.Router();
const createServiceController = require("../controllers-layer/rest-layer/create-service-controller");
const {
  resolveAgent,
  buildToolRegistryFromCatalog,
  invalidateAgentCache,
} = require("./dynamic-agent-manager");
const { refreshCatalog, getCatalogArray } = require("./tool-catalog-manager");
const { hexaLogger } = require("../common/hexa-logger");

function truncateForLog(value, maxLen = 2048) {
  if (value == null) return null;
  const str = typeof value === "string" ? value : JSON.stringify(value);
  return str.length > maxLen ? str.slice(0, maxLen) + "..." : str;
}

// Resolve session using standard service controller
async function resolveSession(req, res) {
  if (req.session) return;
  try {
    const controller = createServiceController(
      "agentHub",
      "agentHub",
      req,
      res,
    );
    await controller.init();
  } catch (_) {
    req.session = null;
  }
}

// Get compiled agent runtimes (injected by express-app.ejs)
function getCompiledAgents(req) {
  return req.app.agentRuntimes || {};
}

// Log execution to sys_agentExecution
async function logExecution(
  agentName,
  agentType,
  source,
  session,
  input,
  output,
  metrics,
) {
  try {
    const { createSys_agentExecution } = require("dbLayer");
    await createSys_agentExecution({
      agentName,
      agentType,
      source,
      userId: session?.userId || null,
      input: input ? JSON.stringify(input).slice(0, 10000) : null,
      output: output ? JSON.stringify(output).slice(0, 10000) : null,
      toolCalls: metrics?.toolCalls || 0,
      tokenUsage: metrics?.tokenUsage || null,
      durationMs: metrics?.durationMs || 0,
      status: metrics?.error
        ? "error"
        : metrics?.timeout
          ? "timeout"
          : "success",
      error: metrics?.error || null,
    });
  } catch (err) {
    console.warn("[AgentHubRouter] Failed to log execution:", err.message);
  }
}

// ============================================================================
// Agent Execution: POST /agents/:agentName
// ============================================================================
router.post("/agents/:agentName", async (req, res) => {
  const startTime = Date.now();
  const { agentName } = req.params;

  try {
    await resolveSession(req, res);

    const compiledAgents = getCompiledAgents(req);
    const agentConfig = await resolveAgent(agentName, compiledAgents);

    if (!agentConfig) {
      return res
        .status(404)
        .json({ result: "ERR", message: `Agent '${agentName}' not found` });
    }

    if (agentConfig.disabled) {
      return res
        .status(403)
        .json({ result: "ERR", message: `Agent '${agentName}' is disabled` });
    }

    // Check auth if required
    const authRequired = agentConfig.config?.authRequired !== false;
    if (authRequired && !req.session?.userId) {
      return res
        .status(401)
        .json({ result: "ERR", message: "Authentication required" });
    }

    // For design-time agents with compiled runtimes — use them directly (with overrides)
    if (agentConfig.type === "design" && compiledAgents[agentName]) {
      const runtime = compiledAgents[agentName];
      // TODO: Apply overrides to runtime (provider, model, systemPrompt, tools)
      // AgentRuntime.execute persists the sys_agentExecution row itself
      // (with the exact toolCalls count, durationMs, tokenUsage), so the
      // router does NOT call logExecution here — that would double-write.
      const result = await runtime.execute(req, null, {
        source: "rest",
        userId: req.session?.userId || null,
        agentType: "design",
      });
      const durationMs = Date.now() - startTime;
      hexaLogger.insertInfo(
        "AgentExecution",
        {
          agentName,
          source: "rest",
          status: "success",
          serviceName: "agentHub",
          agentType: "design",
        },
        "agent-hub-router",
        {
          durationMs,
          input: truncateForLog(req.body),
          output: truncateForLog(result),
        },
      );
      return res.json({ success: true, data: result });
    }

    return res
      .status(500)
      .json({ result: "ERR", message: "Agent could not be executed" });
  } catch (err) {
    const durationMs = Date.now() - startTime;
    // AgentRuntime persists the failure row itself when its execute()
    // throws; the router only emits the stdout/hexaLogger trail here so
    // the error is visible in the structured log feed alongside the row.
    hexaLogger.insertError(
      "AgentExecution",
      { agentName, source: "rest", status: "error", serviceName: "agentHub" },
      "agent-hub-router",
      { durationMs, input: truncateForLog(req.body), error: err.message },
    );
    console.error(
      `[AgentHubRouter] Error executing agent '${agentName}':`,
      err.message,
    );
    return res.status(500).json({ result: "ERR", message: err.message });
  }
});

// ============================================================================
// Agent SSE Streaming: POST /agents/:agentName/stream
// ============================================================================
router.post("/agents/:agentName/stream", async (req, res) => {
  const { agentName } = req.params;

  try {
    await resolveSession(req, res);

    const compiledAgents = getCompiledAgents(req);
    const agentConfig = await resolveAgent(agentName, compiledAgents);

    if (!agentConfig) {
      return res
        .status(404)
        .json({ result: "ERR", message: `Agent '${agentName}' not found` });
    }

    if (agentConfig.disabled) {
      return res
        .status(403)
        .json({ result: "ERR", message: `Agent '${agentName}' is disabled` });
    }

    const authRequired = agentConfig.config?.authRequired !== false;
    if (authRequired && !req.session?.userId) {
      return res
        .status(401)
        .json({ result: "ERR", message: "Authentication required" });
    }

    // SSE headers
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    res.flushHeaders();

    // For design-time agents with compiled runtimes
    if (agentConfig.type === "design" && compiledAgents[agentName]) {
      const runtime = compiledAgents[agentName];
      const sseController = {
        send(data) {
          res.write(`event: chunk\ndata: ${JSON.stringify(data)}\n\n`);
        },
        complete() {
          res.write(`event: complete\ndata: {}\n\n`);
          res.end();
        },
        error(err) {
          res.write(
            `event: error\ndata: ${JSON.stringify({ error: err.message })}\n\n`,
          );
          res.end();
        },
      };
      const result = await runtime.execute(req, sseController, {
        source: "sse",
        userId: req.session?.userId || null,
        agentType: "design",
      });
      hexaLogger.insertInfo(
        "AgentExecution",
        {
          agentName,
          source: "sse",
          status: "success",
          serviceName: "agentHub",
          agentType: "design",
        },
        "agent-hub-router",
        { input: truncateForLog(req.body), output: truncateForLog(result) },
      );
      return;
    }

    res.write(
      `event: error\ndata: ${JSON.stringify({ error: "Agent could not be executed" })}\n\n`,
    );
    res.end();
  } catch (err) {
    hexaLogger.insertError(
      "AgentExecution",
      { agentName, source: "sse", status: "error", serviceName: "agentHub" },
      "agent-hub-router",
      { input: truncateForLog(req.body), error: err.message },
    );
    console.error(
      `[AgentHubRouter] SSE error for agent '${agentName}':`,
      err.message,
    );
    if (!res.headersSent) {
      return res.status(500).json({ result: "ERR", message: err.message });
    }
    res.write(
      `event: error\ndata: ${JSON.stringify({ error: err.message })}\n\n`,
    );
    res.end();
  }
});

// ============================================================================
// Tool Catalog: GET /tools and POST /tools/refresh
// ============================================================================
router.get("/tools", async (req, res) => {
  try {
    await resolveSession(req, res);
    if (!req.session?.userId) {
      return res
        .status(401)
        .json({ result: "ERR", message: "Authentication required" });
    }

    const catalog = getCatalogArray();
    res.json({
      success: true,
      count: catalog.length,
      tools: catalog.map((t) => ({
        toolName: t.toolName,
        serviceName: t.serviceName,
        description: t.description,
      })),
    });
  } catch (err) {
    res.status(500).json({ result: "ERR", message: err.message });
  }
});

router.post("/tools/refresh", async (req, res) => {
  try {
    await resolveSession(req, res);
    if (!req.session?.userId) {
      return res
        .status(401)
        .json({ result: "ERR", message: "Authentication required" });
    }

    const tools = await refreshCatalog();
    res.json({
      success: true,
      message: `Tool catalog refreshed: ${tools.length} tools`,
      count: tools.length,
    });
  } catch (err) {
    res.status(500).json({ result: "ERR", message: err.message });
  }
});

// ============================================================================
// Agent Cache Invalidation: POST /agents/:agentName/invalidate
// ============================================================================
router.post("/agents/:agentName/invalidate", async (req, res) => {
  try {
    await resolveSession(req, res);
    if (!req.session?.userId) {
      return res
        .status(401)
        .json({ result: "ERR", message: "Authentication required" });
    }

    invalidateAgentCache(req.params.agentName);
    res.json({
      success: true,
      message: `Cache invalidated for agent: ${req.params.agentName}`,
    });
  } catch (err) {
    res.status(500).json({ result: "ERR", message: err.message });
  }
});

module.exports = router;
